function distribution(averages=false){const values=averages?means():dataset().map(p=>p.epsilon),ref=averages?MU:0,center=averages?MU+s.bias:0,spread=averages?M.se(s.sigma,s.n):s.sigma,lo=Math.min(ref,center-4*spread,...values),hi=Math.max(ref,center+4*spread,...values),mid=(lo+hi)/2,range=Math.max((hi-lo)/2*1.07,.5),k=5/range,h=M.histogram(values,mid-range,mid+range,averages?70:32),peak=Math.max(...h.map(p=>p.density),M.pdf(center,center,spread));w.line([[-5.3,.6,0],[5.3,.6,0]],'#8ca18e',1.3);for(const b of h)if(b.count>0)w.box((b.x-mid)*k,.62,0,9.2/h.length,b.density/peak*3.25,.5,'#9fc2b4');const curve=[];if(s.distribution==='normal'||averages){for(let i=0;i<=160;i++){const x=center-4*spread+8*spread*i/160;curve.push([(x-mid)*k,.65+M.pdf(x,center,spread)/peak*3.25,-.32])}}else if(s.distribution==='uniform'){const r=Math.sqrt(3)*s.sigma,y=.65+1/(2*r)/peak*3.25;curve.push([(-r-mid)*k,.65,-.32],[(-r-mid)*k,y,-.32],[(r-mid)*k,y,-.32],[(r-mid)*k,.65,-.32])}else{for(let i=0;i<=140;i++){const x=-s.sigma+(hi+s.sigma)*i/140;curve.push([(x-mid)*k,.65+Math.exp(-(x/s.sigma+1))/s.sigma/peak*3.25,-.32])}}w.line(curve,'#397e75',2);const rx=(ref-mid)*k;w.line([[rx,.6,-.5],[rx,4.5,-.5]],'#ba9559',1.3,{dash:[5,4]});for(let j=-2;j<=2;j++)w.label([j*2.5,.26,0],(mid+j*range/2).toFixed(1),{size:11});w.label([0,-.22,0],averages?'组均值 x̄ / mg P·L⁻¹':'随机误差 ε = X−μ−b / mg P·L⁻¹',{size:13,pill:true});w.label([0,5.45,0],averages?`180 组，每组 ${s.n} 次 · 长期中心 ${(MU+s.bias).toFixed(1)}`:'800 次随机波动 · 以 0 为长期中心',{size:16,pill:true});w.label([0,4.78,0],averages?(s.distribution==='normal'?'正态母体：均值标准差 σ/√n':'曲线为均值的正态近似，n 小或偏态强时可能不充分'):'直方图为模拟频率密度；曲线为所选概率密度',{size:12,pill:true})}
